const groups=buildUiGroups(rows);const sectionOrder=['Personal Loan','Auto Loan Personal','Housing Loan','Credit Card'];const ordered=[...groups.filter(g=>sectionOrder.includes(g.loan_type)).sort((a,b)=>sectionOrder.indexOf(a.loan_type)-sectionOrder.indexOf(b.loan_type)),...groups.filter(g=>!sectionOrder.includes(g.loan_type))];
